    pub(crate) fn compare_flexray_communication_connector(
        &self,
        other: &Document,
        a: &FlexrayCommunicationConnector,
        b: &FlexrayCommunicationConnector,
        path: &str,
    ) -> Result<(), String> {
        self.compare_communication_connector(other, a.base(), b.base(), path)?;
        if a.get_nm_ready_sleep_time() != b.get_nm_ready_sleep_time() {
            return Err(format!("{path}: NM_READY_SLEEP_TIME mismatch"));
        }
        if a.get_wake_up_channel() != b.get_wake_up_channel() {
            return Err(format!("{path}: WAKE_UP_CHANNEL mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_flexray_communication_controller(
        &self,
        other: &Document,
        a: &FlexrayCommunicationController,
        b: &FlexrayCommunicationController,
        path: &str,
    ) -> Result<(), String> {
        self.compare_communication_controller(other, a.base(), b.base(), path)?;
        if a.get_accepted_startup_range() != b.get_accepted_startup_range() {
            return Err(format!("{path}: ACCEPTED_STARTUP_RANGE mismatch"));
        }
        if a.get_allow_halt_due_to_clock() != b.get_allow_halt_due_to_clock() {
            return Err(format!("{path}: ALLOW_HALT_DUE_TO_CLOCK mismatch"));
        }
        if a.get_allow_passive_to_active() != b.get_allow_passive_to_active() {
            return Err(format!("{path}: ALLOW_PASSIVE_TO_ACTIVE mismatch"));
        }
        if a.get_cluster_drift_damping() != b.get_cluster_drift_damping() {
            return Err(format!("{path}: CLUSTER_DRIFT_DAMPING mismatch"));
        }
        if a.get_decoding_correction() != b.get_decoding_correction() {
            return Err(format!("{path}: DECODING_CORRECTION mismatch"));
        }
        if a.get_delay_compensation_a() != b.get_delay_compensation_a() {
            return Err(format!("{path}: DELAY_COMPENSATION_A mismatch"));
        }
        if a.get_delay_compensation_b() != b.get_delay_compensation_b() {
            return Err(format!("{path}: DELAY_COMPENSATION_B mismatch"));
        }
        if a.get_external_sync() != b.get_external_sync() {
            return Err(format!("{path}: EXTERNAL_SYNC mismatch"));
        }
        if a.get_extern_offset_correction() != b.get_extern_offset_correction() {
            return Err(format!("{path}: EXTERN_OFFSET_CORRECTION mismatch"));
        }
        if a.get_extern_rate_correction() != b.get_extern_rate_correction() {
            return Err(format!("{path}: EXTERN_RATE_CORRECTION mismatch"));
        }
        if a.get_fall_back_internal() != b.get_fall_back_internal() {
            return Err(format!("{path}: FALL_BACK_INTERNAL mismatch"));
        }
        let list_a = a.get_flexray_fifos();
        let list_b = b.get_flexray_fifos();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: FLEXRAY_FIFOS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.flexray_fifo_configurations.get(*x).ok_or_else(|| {
                format!("{path}.FLEXRAY_FIFOS[{index}]: id not found in own arena")
            })?;
            let y = other.flexray_fifo_configurations.get(*y).ok_or_else(|| {
                format!("{path}.FLEXRAY_FIFOS[{index}]: id not found in other arena")
            })?;
            self.compare_flexray_fifo_configuration(
                other,
                x,
                y,
                &format!("{path}.FLEXRAY_FIFOS[{index}]"),
            )?;
        }
        if a.get_key_slot_id() != b.get_key_slot_id() {
            return Err(format!("{path}: KEY_SLOT_ID mismatch"));
        }
        if a.get_key_slot_only_enabled() != b.get_key_slot_only_enabled() {
            return Err(format!("{path}: KEY_SLOT_ONLY_ENABLED mismatch"));
        }
        if a.get_key_slot_used_for_start_up() != b.get_key_slot_used_for_start_up() {
            return Err(format!("{path}: KEY_SLOT_USED_FOR_START_UP mismatch"));
        }
        if a.get_key_slot_used_for_sync() != b.get_key_slot_used_for_sync() {
            return Err(format!("{path}: KEY_SLOT_USED_FOR_SYNC mismatch"));
        }
        if a.get_latest_tx() != b.get_latest_tx() {
            return Err(format!("{path}: LATEST_TX mismatch"));
        }
        if a.get_listen_timeout() != b.get_listen_timeout() {
            return Err(format!("{path}: LISTEN_TIMEOUT mismatch"));
        }
        if a.get_macro_initial_offset_a() != b.get_macro_initial_offset_a() {
            return Err(format!("{path}: MACRO_INITIAL_OFFSET_A mismatch"));
        }
        if a.get_macro_initial_offset_b() != b.get_macro_initial_offset_b() {
            return Err(format!("{path}: MACRO_INITIAL_OFFSET_B mismatch"));
        }
        if a.get_maximum_dynamic_payload_length() != b.get_maximum_dynamic_payload_length() {
            return Err(format!("{path}: MAXIMUM_DYNAMIC_PAYLOAD_LENGTH mismatch"));
        }
        if a.get_micro_initial_offset_a() != b.get_micro_initial_offset_a() {
            return Err(format!("{path}: MICRO_INITIAL_OFFSET_A mismatch"));
        }
        if a.get_micro_initial_offset_b() != b.get_micro_initial_offset_b() {
            return Err(format!("{path}: MICRO_INITIAL_OFFSET_B mismatch"));
        }
        if a.get_micro_per_cycle() != b.get_micro_per_cycle() {
            return Err(format!("{path}: MICRO_PER_CYCLE mismatch"));
        }
        if a.get_microtick_duration() != b.get_microtick_duration() {
            return Err(format!("{path}: MICROTICK_DURATION mismatch"));
        }
        if a.get_nm_vector_early_update() != b.get_nm_vector_early_update() {
            return Err(format!("{path}: NM_VECTOR_EARLY_UPDATE mismatch"));
        }
        if a.get_offset_correction_out() != b.get_offset_correction_out() {
            return Err(format!("{path}: OFFSET_CORRECTION_OUT mismatch"));
        }
        if a.get_rate_correction_out() != b.get_rate_correction_out() {
            return Err(format!("{path}: RATE_CORRECTION_OUT mismatch"));
        }
        if a.get_samples_per_microtick() != b.get_samples_per_microtick() {
            return Err(format!("{path}: SAMPLES_PER_MICROTICK mismatch"));
        }
        if a.get_second_key_slot_id() != b.get_second_key_slot_id() {
            return Err(format!("{path}: SECOND_KEY_SLOT_ID mismatch"));
        }
        if a.get_two_key_slot_mode() != b.get_two_key_slot_mode() {
            return Err(format!("{path}: TWO_KEY_SLOT_MODE mismatch"));
        }
        if a.get_wake_up_pattern() != b.get_wake_up_pattern() {
            return Err(format!("{path}: WAKE_UP_PATTERN mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_flexray_fifo_configuration(
        &self,
        other: &Document,
        a: &FlexrayFifoConfiguration,
        b: &FlexrayFifoConfiguration,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_admit_without_message_id() != b.get_admit_without_message_id() {
            return Err(format!("{path}: ADMIT_WITHOUT_MESSAGE_ID mismatch"));
        }
        if a.get_base_cycle() != b.get_base_cycle() {
            return Err(format!("{path}: BASE_CYCLE mismatch"));
        }
        if a.get_channel_ref() != b.get_channel_ref() {
            return Err(format!("{path}: CHANNEL_REF mismatch"));
        }
        if a.get_cycle_repetition() != b.get_cycle_repetition() {
            return Err(format!("{path}: CYCLE_REPETITION mismatch"));
        }
        if a.get_fifo_depth() != b.get_fifo_depth() {
            return Err(format!("{path}: FIFO_DEPTH mismatch"));
        }
        let list_a = a.get_fifo_range();
        let list_b = b.get_fifo_range();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: FIFO_RANGE length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .flexray_fifo_ranges
                .get(*x)
                .ok_or_else(|| format!("{path}.FIFO_RANGE[{index}]: id not found in own arena"))?;
            let y = other.flexray_fifo_ranges.get(*y).ok_or_else(|| {
                format!("{path}.FIFO_RANGE[{index}]: id not found in other arena")
            })?;
            self.compare_flexray_fifo_range(other, x, y, &format!("{path}.FIFO_RANGE[{index}]"))?;
        }
        if a.get_msg_id_mask() != b.get_msg_id_mask() {
            return Err(format!("{path}: MSG_ID_MASK mismatch"));
        }
        if a.get_msg_id_match() != b.get_msg_id_match() {
            return Err(format!("{path}: MSG_ID_MATCH mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_flexray_fifo_range(
        &self,
        _other: &Document,
        a: &FlexrayFifoRange,
        b: &FlexrayFifoRange,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_range_max() != b.get_range_max() {
            return Err(format!("{path}: RANGE_MAX mismatch"));
        }
        if a.get_range_min() != b.get_range_min() {
            return Err(format!("{path}: RANGE_MIN mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_flexray_physical_channel(
        &self,
        other: &Document,
        a: &FlexrayPhysicalChannel,
        b: &FlexrayPhysicalChannel,
        path: &str,
    ) -> Result<(), String> {
        self.compare_physical_channel(other, a.base(), b.base(), path)?;
        if a.get_channel_name() != b.get_channel_name() {
            return Err(format!("{path}: CHANNEL_NAME mismatch"));
        }
        Ok(())
    }
